"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AREA_ROWS,
  BENCHMARK_ROWS,
  CENSUS_CONTRAST,
  COLORS,
  COMPOSITION_2021,
  HEADLINE,
  SOURCE_NOTE,
  VIZ_MARKERS,
  WEIGHT_LENS,
  areasForBasin,
  fmtPct,
  fmtPp,
  pathForMetric,
  sortedAreas,
  type OceanBasin,
} from "@/data/biologically-unsustainable-stocks-share-2026-data";

// viz-types: unsustainable path area+line, area ladder bars, composition pie, weight dual-line, benchmark bars, census scatter | layout: default

type ViewId = "path" | "areas" | "composition" | "benchmarks";
type MetricLens = "unsustainable" | "sustainable";
type SortMode = "unsustainable-desc" | "sustainable-desc" | "code";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="flex flex-wrap gap-1">
        {options.map((o) => {
          const active = o.id === value;
          return (
            <button
              key={o.id}
              type="button"
              onClick={() => onChange(o.id)}
              className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
                active
                  ? "bg-slate-900 text-white"
                  : "bg-slate-100 text-slate-700 hover:bg-slate-200"
              }`}
            >
              {o.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function MeterStrip() {
  return (
    <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
      {[
        {
          k: "Unsustainable stock %",
          v: fmtPct(HEADLINE.unsustainablePct2021),
          s: `2021 equal-stock share (was ${fmtPct(HEADLINE.unsustainablePct2019)} in 2019)`,
        },
        {
          k: "Since 1974",
          v: fmtPp(HEADLINE.deltaPp1974to2021),
          s: `From ${fmtPct(HEADLINE.unsustainablePct1974, 0)} overfished in 1974`,
        },
        {
          k: "Landings-weighted sustainable",
          v: fmtPct(HEADLINE.landingsWeightedSustainablePct2021),
          s: "Larger stocks pull this above the 62.3% stock-count print",
        },
        {
          k: "2019???2021 move",
          v: fmtPp(HEADLINE.deltaPp2019to2021),
          s: "Still rising on the SOFIA panel",
        },
      ].map((m) => (
        <div
          key={m.k}
          className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-50 to-white px-4 py-3"
        >
          <p className="text-xs font-semibold uppercase tracking-wide text-slate-500">
            {m.k}
          </p>
          <p className="mt-1 text-2xl font-bold tabular-nums text-slate-900">
            {m.v}
          </p>
          <p className="mt-1 text-xs text-slate-500">{m.s}</p>
        </div>
      ))}
    </div>
  );
}

function PathPanel({ metric }: { metric: MetricLens }) {
  const data = useMemo(() => pathForMetric(metric), [metric]);
  const stroke =
    metric === "unsustainable" ? COLORS.unsustainable : COLORS.sustainable;
  const fill =
    metric === "unsustainable" ? "rgba(220,38,38,0.18)" : "rgba(14,165,233,0.18)";
  return (
    <ChartCard
      title="Stock-count path"
      subtitle={`${metric === "unsustainable" ? "Unsustainable" : "Sustainable"} share of assessed marine stocks, 1974???2021 (SOFIA panel)`}
    >
      <div className="h-[340px] w-full min-w-0">
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart data={data} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
            <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
            <XAxis dataKey="year" tick={{ fontSize: 11 }} />
            <YAxis
              domain={[0, 100]}
              tick={{ fontSize: 11 }}
              tickFormatter={(v) => `${v}%`}
            />
            <Tooltip
              formatter={(value) => [
                fmtPct(Number(value)),
                metric === "unsustainable" ? "Unsustainable" : "Sustainable",
              ]}
            />
            <Area
              type="monotone"
              dataKey="value"
              stroke="none"
              fill={fill}
              isAnimationActive={false}
            />
            <Line
              type="monotone"
              dataKey="value"
              stroke={stroke}
              strokeWidth={2.5}
              dot={{ r: 3, fill: stroke }}
              isAnimationActive={false}
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>
      <p className="mt-2 text-xs text-slate-500">
        Early decades include chart-approximate midpoints; 2013???2021 prints are
        SOFIA-disclosed.
      </p>
    </ChartCard>
  );
}

function AreasPanel({
  basin,
  metric,
  sortMode,
}: {
  basin: OceanBasin;
  metric: MetricLens;
  sortMode: SortMode;
}) {
  const rows = useMemo(() => {
    const base = areasForBasin(basin);
    if (sortMode === "code") {
      return [...base].sort((a, b) => a.areaCode - b.areaCode);
    }
    if (sortMode === "sustainable-desc") {
      return sortedAreas(base, "sustainable", "desc");
    }
    return sortedAreas(base, "unsustainable", "desc");
  }, [basin, sortMode]);

  const chartData = rows.map((r) => ({
    name: r.shortLabel,
    value: metric === "unsustainable" ? r.unsustainablePct : r.sustainablePct,
    fill:
      metric === "unsustainable"
        ? r.unsustainablePct >= 50
          ? COLORS.unsustainable
          : "#f87171"
        : r.sustainablePct >= 70
          ? COLORS.sustainable
          : "#7dd3fc",
  }));

  return (
    <ChartCard
      title="Area ladder"
      subtitle={`FAO Major Fishing Areas, 2021 ??? ${metric === "unsustainable" ? "unsustainable" : "sustainable"} stock share`}
    >
      <div className="h-[420px] w-full min-w-0">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={chartData}
            layout="vertical"
            margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
          >
            <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" horizontal={false} />
            <XAxis
              type="number"
