      {view === "composition" ? <CompositionPanel /> : null}
      {view === "benchmarks" ? <BenchmarksPanel /> : null}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
