            <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
            <XAxis dataKey="year" tick={{ fontSize: 11 }} />
            <YAxis
              domain={[0, 100]}
              tick={{ fontSize: 11 }}
              tickFormatter={(v) => `${v}%`}
            />
            <Tooltip
              formatter={(value) => [
                fmtPct(Number(value)),
                metric === "unsustainable" ? "Unsustainable" : "Sustainable",
              ]}
            />
            <Area
              type="monotone"
              dataKey="value"
              stroke="none"
              fill={fill}
              isAnimationActive={false}
