        <ToggleGroup
          label="Quick metric"
          value={metric}
          options={[
            { id: "unsustainable", label: "Unsustainable" },
            { id: "sustainable", label: "Sustainable" },
          ]}
          onChange={setMetric}
        />
      </div>

