            <YAxis
              type="category"
              dataKey="name"
              width={118}
              tick={{ fontSize: 10 }}
            />
            <Tooltip formatter={(value) => [fmtPct(Number(value)), "Share"]} />
            <Bar dataKey="value" radius={[0, 4, 4, 0]} isAnimationActive={false}>
              {chartData.map((d) => (
