                stroke={COLORS.landings}
                fill="rgba(5,150,105,0.12)"
                strokeWidth={2}
                isAnimationActive={false}
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>
    </div>
  );
